using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using TransPort.Web.Models;using TransPort.Web.Services;
namespace TransPort.Web.Areas.Gestion.Controllers;
[Area("Gestion"),Authorize(Roles="AdministradorGeneral,Gerente,Empleado,Operativo"),Route("gestion/producciones")]
public sealed class ProduccionesController(ITransportApiClient api,ILogger<ProduccionesController> log):Controller
{
 [HttpGet("")]public async Task<IActionResult>Index(string?estado,int?sedeId,DateTime?fechaDesde,DateTime?fechaHasta,CancellationToken ct){try{return View(new ProduccionPaginaViewModel{Estado=estado,SedeId=sedeId,FechaDesde=fechaDesde,FechaHasta=fechaHasta,Ordenes=await api.ProduccionesAsync(estado,sedeId,fechaDesde,fechaHasta,ct),Opciones=await api.ProduccionOpcionesAsync(ct)});}catch(Exception e)when(e is HttpRequestException or TransportApiException){log.LogError(e,"No se cargó producción");TempData["Error"]="No fue posible consultar producción.";return View(new ProduccionPaginaViewModel());}}
 [HttpPost("crear")]public async Task<IActionResult>Crear(ProduccionCrearViewModel m,CancellationToken ct){if(!ModelState.IsValid||m.ArticuloEntradaId==m.ArticuloSalidaId){TempData["Error"]="Revise los datos de la orden.";return RedirectToAction(nameof(Index));}try{var id=await api.CrearProduccionAsync(m,ct);TempData["Exito"]="Orden creada.";return RedirectToAction(nameof(Detalle),new{id});}catch(TransportApiException e){log.LogWarning(e,"No se creó producción");TempData["Error"]="No fue posible crear la orden; revise planta, artículos y permisos.";return RedirectToAction(nameof(Index));}}
 [HttpGet("{id:long}")]public async Task<IActionResult>Detalle(long id,CancellationToken ct){var x=await api.ProduccionAsync(id,ct);return x is null?NotFound():View(x);}
 [HttpPost("{id:long}/estado")]public async Task<IActionResult>Estado(long id,string estado,decimal?cantidadSalidaReal,decimal?cantidadMerma,decimal?costoUnitario,string?comentario,CancellationToken ct){try{await api.CambiarEstadoProduccionAsync(id,estado,cantidadSalidaReal,cantidadMerma,costoUnitario,comentario,ct);TempData["Exito"]="Estado actualizado.";}catch(TransportApiException e){log.LogWarning(e,"No cambió producción");TempData["Error"]="No fue posible cambiar el estado; revise inventario, etapas y resultados.";}return RedirectToAction(nameof(Detalle),new{id});}
 [HttpPost("{id:long}/etapas/{etapaId:long}")]public async Task<IActionResult>Etapa(long id,long etapaId,string?observacion,CancellationToken ct){try{await api.CompletarEtapaProduccionAsync(id,etapaId,observacion,ct);TempData["Exito"]="Etapa completada.";}catch(TransportApiException e){log.LogWarning(e,"No completó etapa");TempData["Error"]="Solo puede completar la etapa activa.";}return RedirectToAction(nameof(Detalle),new{id});}
 [HttpPost("{id:long}/eliminar"),Authorize(Roles="AdministradorGeneral")]public async Task<IActionResult>Eliminar(long id,CancellationToken ct){await api.EliminarProduccionAsync(id,ct);return RedirectToAction(nameof(Index));}
}
